CREATE TYPE "public"."Gender" AS ENUM ('MALE', 'FEMALE', 'OTHER', 'UNSPECIFIED');
CREATE TYPE "public"."MilitaryServiceStatus" AS ENUM ('COMPLETED', 'EXEMPT');
CREATE TYPE "public"."SettlementStatus" AS ENUM ('PENDING', 'COMPLETED');
ALTER TYPE "public"."AuditAction" ADD VALUE IF NOT EXISTS 'DOCUMENT_REPLACE';
ALTER TYPE "public"."AuditAction" ADD VALUE IF NOT EXISTS 'DOCUMENT_DELETE';
ALTER TYPE "public"."AuditAction" ADD VALUE IF NOT EXISTS 'DOCUMENT_RESTORE';
ALTER TYPE "public"."AuditAction" ADD VALUE IF NOT EXISTS 'SETTLEMENT_CHANGE';
ALTER TYPE "public"."AuditAction" ADD VALUE IF NOT EXISTS 'MILITARY_SERVICE_CHANGE';
ALTER TABLE "public"."Employee" ADD COLUMN "address" TEXT, ADD COLUMN "insuranceStartDate" TIMESTAMP(3), ADD COLUMN "insuranceEndDate" TIMESTAMP(3), ADD COLUMN "educationalInstitution" TEXT, ADD COLUMN "gender" "public"."Gender", ADD COLUMN "militaryServiceStatus" "public"."MilitaryServiceStatus", ADD COLUMN "militaryServiceDate" TIMESTAMP(3), ADD COLUMN "militaryExemptionType" TEXT;
ALTER TABLE "public"."Document" ADD COLUMN "deletedAt" TIMESTAMP(3), ADD COLUMN "deletedById" TEXT;
CREATE INDEX "Document_employeeId_deletedAt_idx" ON "public"."Document"("employeeId", "deletedAt");
CREATE TABLE "public"."DocumentVersion" ("id" TEXT NOT NULL, "documentId" TEXT NOT NULL, "version" INTEGER NOT NULL, "originalName" TEXT NOT NULL, "storageName" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "sizeBytes" INTEGER NOT NULL, "uploadedById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DocumentVersion_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DocumentVersion_documentId_version_key" ON "public"."DocumentVersion"("documentId", "version");
CREATE INDEX "DocumentVersion_documentId_createdAt_idx" ON "public"."DocumentVersion"("documentId", "createdAt");
CREATE TABLE "public"."Settlement" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "status" "public"."SettlementStatus" NOT NULL DEFAULT 'PENDING', "settlementDate" TIMESTAMP(3), "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Settlement_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Settlement_employeeId_key" ON "public"."Settlement"("employeeId");
CREATE TABLE "public"."Notification" ("id" TEXT NOT NULL, "eventId" TEXT NOT NULL, "recipientId" TEXT NOT NULL, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Notification_eventId_recipientId_key" ON "public"."Notification"("eventId", "recipientId");
CREATE INDEX "Notification_recipientId_readAt_createdAt_idx" ON "public"."Notification"("recipientId", "readAt", "createdAt");
ALTER TABLE "public"."Document" ADD CONSTRAINT "Document_deletedById_fkey" FOREIGN KEY ("deletedById") REFERENCES "public"."User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "public"."DocumentVersion" ADD CONSTRAINT "DocumentVersion_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "public"."Document"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."DocumentVersion" ADD CONSTRAINT "DocumentVersion_uploadedById_fkey" FOREIGN KEY ("uploadedById") REFERENCES "public"."User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "public"."Settlement" ADD CONSTRAINT "Settlement_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "public"."Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."Notification" ADD CONSTRAINT "Notification_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "public"."AuditEvent"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."Notification" ADD CONSTRAINT "Notification_recipientId_fkey" FOREIGN KEY ("recipientId") REFERENCES "public"."User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
